MagickBooleanType SkipUncompressedMipmaps(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
    size_t level;
    size_t width;
    size_t height;

    if (EOFBlob(image, exception)) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, " Unexpected end of file", "`%s'", image->filename);
        return MagickFalse;
    }

    if ((dds_info->mipmap_count > 1) && (dds_info->dds_header->ddshdr->surfaceflags & DDSD_MIPMAPCOUNT)) {
        width = (size_t) dds_info->dds_header->ddshdr->width;
        height = (size_t) dds_info->dds_header->ddshdr->height;

        for (level = 1; level < dds_info->mipmap_count; level++) {
            if ((width != 0) || (height != 0)) {
                size_t row_size = width * (size_t) pixel_size;
                size_t image_size = row_size * height;
                if (SeekBlob(image, (MagickSizeType) image_size, SEEK_CUR) != image->scene)
                    return MagickFalse;
                width = width >> 1;
                height = height >> 1;
            }
            else
                break;
        }
    }

    return MagickTrue;
}

MagickBooleanType SkipUncompressedMipmaps(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
  if ((dds_info->mipmap_levels > 1) && ((dds_info->flags & DDSD_MIPMAPCOUNT) != 0)) {
    size_t width = dds_info->width;
    size_t height = dds_info->height;
    ssize_t offset = 0;

    for (ssize_t level = 1; level < dds_info->mipmap_levels; level++) {
      if ((width == 0) || (height == 0)) break;

      size_t mipmap_size = width * height * pixel_size;
      offset += (ssize_t)mipmap_size;

      if (SeekBlob(image, offset, SEEK_SET) == MagickFalse) {
        (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError, "UnableToSeekImage", "%s", image->filename);
        return MagickFalse;
      }

      width >>= 1;
      height >>= 1;
    }
    return MagickFalse;
  }
  return MagickTrue;
}

MagickBooleanType SkipUncompressedMipmapDDSImages(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
    // Check for unexpected end of file
    if (EODDS(image, dds_info)) {
        return MagickFalse;
    }

    // If no mipmaps or not a texture or cube map, return MagickTrue
    if (!(dds_info->mipmap_levels > 1) || (!(dds_info->texture) && !(dds_info->cube_map)))
        return MagickTrue;

    // Skip mipmap images
    MagickSizeType offset = 0;
    MagickSizeType width = image->columns;
    MagickSizeType height = image->rows;

    for (MagickSizeType level = 1; level < dds_info->mipmap_levels; level++) {
        MagickSizeType level_width = width / 2;
        MagickSizeType level_height = height / 2;
        MagickSizeType level_size = level_width * level_height * pixel_size;

        if (level_width == 0 || level_height == 0)
            break;

        image->offset += level_size;
        offset += level_size;

        width = level_width;
        height = level_height;
    }

    return MagickTrue;
}

MagickBooleanType SkipUncompressedMipmaps(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
    if (dds_info->mipmap_count > 1) {
        if ((dds_info->flags & DDSTexture) || (dds_info->flags & DDS立方图)) {
            MagickSizeType width = dds_info->width;
            MagickSizeType height = dds_info->height;
            MagickSizeType level = 0;
            MagickBooleanType status = MagickTrue;

            do {
                MagickSizeType level_width = width > 0 ? width : 1;
                MagickSizeType level_height = height > 0 ? height : 1;
                MagickSizeType image_size = level_width * level_height * pixel_size;
                MagickOffsetType offset = (MagickOffsetType) image_size;

                if (SeekBlob(image, offset, SEEK_CUR) != offset) {
                    status = MagickFalse;
                    break;
                }

                if (level_width > 1)
                    width = level_width / 2;
                else
                    width = 0;

                if (level_height > 1)
                    height = level_height / 2;
                else
                    height = 0;

                level++;
            } while ((width > 0) || (height > 0));

            if (!status) {
                (void) ThrowMagickException(exception, GetMagickModule(), CoderError, "UnexpectedEndOfFile", " ");
                return MagickFalse;
            }

            return MagickFalse;
        }
    }

    return MagickTrue;
}

MagickBooleanType SkipUncompressedMipmapDDSImages(Image *image, DDSInfo *dds_info, int pixel_size, ExceptionInfo *exception) {
    /* Check for EOF */
    if (EofBlob(image)) {
        (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnableToSkipMipmapImages", "`%s' is corrupt", image->filename);
        return MagickFalse;
    }

    /* Check if the DDS file has mipmaps and is a texture or cube map */
    if ((dds_info->mipmaps > 1) && (dds_info->dds_header.dwCaps1 & (DDSCAPS_TEXTURE | DDSCAPS_CUBEMAP))) {
        size_t width = (size_t) dds_info->dds_header.dwWidth;
        size_t height = (size_t) dds_info->dds_header.dwHeight;

        while ((width != 0) || (height != 0)) {
            size_t mipmap_size = width * height * (size_t) pixel_size;

            /* Skip the mipmap data */
            if (SeekBlob(image, (MagickSizeType) mipmap_size, SEEK_CUR) == (MagickSizeType) -1) {
                (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnableToSkipMipmapImages", "`%s' is corrupt", image->filename);
                return MagickFalse;
            }

            /* Calculate next mipmap dimensions */
            width = (width > 1) ? width / 2 : 0;
            height = (height > 1) ? height / 2 : 0;
        }
        return MagickTrue;
    }

    return MagickTrue;
}
